  { tag: "button",  label: null },
  { tag: "nav",     label: null },
  { tag: "footer",  label: null },
];

const LANDMARK_ROLES = {
  main: "main",
  header: "banner",
  nav: "navigation",
  section: "region",
  footer: "contentinfo",
};

function auditOutline(nodes) {
  let landmarks = 0;
  const roles = [];
  const unnamed = [];
  for (const node of nodes) {
    const role = LANDMARK_ROLES[node.tag];
    if (role) {
      landmarks += 1;
      roles.push(role);
    }
    if ((node.tag === "section" || node.tag === "nav") && node.label == null) {
      unnamed.push(node.tag);
    }
  }
  return { landmarks, roles, unnamed };
}

const result = auditOutline(NODES);
console.log("landmarks=", result.landmarks);
console.log("roles=", result.roles);
console.log("unnamed=", result.unnamed);

