const MIN_TRACK = 220;
const GAP = 16;
const CONTAINERS = [200, 480, 760, 1000];

function resolveGrid(containerWidth) {
  const columns = Math.max(1, Math.floor((containerWidth + GAP) / (MIN_TRACK + GAP)));
  const raw = (containerWidth - (columns - 1) * GAP) / columns;
  const trackWidth = Math.round(raw * 100) / 100;
  return { columns, trackWidth };
}

const results = CONTAINERS.map((w) => {
  const { columns, trackWidth } = resolveGrid(w);
  return { w, columns, trackWidth };
});
for (const r of results) {
  console.log(r.w + "px ->", r.columns, "cols @", r.trackWidth + "px");
}

