function uploadMachine(state, event) {
  switch (state.status) {
    case 'idle':
      if (event.type === 'SELECT') return { status: 'selected' };
      return state;
    case 'selected':
      if (event.type === 'REMOVE') return { status: 'idle' };
      if (event.type === 'UPLOAD') return { status: 'uploading' };
      return state;
    case 'uploading':
      if (event.type === 'DONE') return { status: 'done' };
      if (event.type === 'FAIL') return { status: 'failed', error: event.message };
      return state;
    case 'failed':
      if (event.type === 'RETRY') return { status: 'uploading' };
      return state;
    default:
      return state;
  }
}

const events = [
  { type: 'SELECT' },
  { type: 'UPLOAD' },
  { type: 'FAIL', message: 'timeout' },
  { type: 'RETRY' },
  { type: 'DONE' },
  { type: 'RETRY' },        // ignored: not legal once we reach 'done'
];

let state = { status: 'idle' };
const trace = [];
for (const ev of events) {
  state = uploadMachine(state, ev);
  trace.push(state.status);
}
console.log("trace=", trace);
console.log("final=", state);

