const RAW_RESPONSE = {
  orders: [
    { id: "a1", status: "shipped", total: 42 },
    { id: "a2", status: "flying", total: 10 },
    { id: "a3", status: "delivered", total: -5 },
    { id: "a4", status: "pending", total: 0 },
    { id: 99, status: "pending", total: 7 },
  ],
};

const STATUSES = ["pending", "shipped", "delivered"];

function isValidOrder(o) {
  if (typeof o.id !== "string") return false;
  if (!STATUSES.includes(o.status)) return false;
  if (typeof o.total !== "number" || o.total < 0) return false;
  return true;
}

function parseOrders(response) {
  const valid = [];
  const rejected = [];
  for (const o of response.orders) {
    if (isValidOrder(o)) valid.push(o.id);
    else rejected.push(o.id);
  }
  return { valid, rejected };
}

const result = parseOrders(RAW_RESPONSE);
