const ORDERS = [
  { id: 1, status: 'open' },
  { id: 2, status: 'shipped' },
  { id: 3, status: 'open' },
  { id: 4, status: 'open' },
  { id: 5, status: 'shipped' },
  { id: 6, status: 'open' },
  { id: 7, status: 'shipped' },
  { id: 8, status: 'open' },
];

const LIMIT = 3;

function parseQuery(qs) {
  const params = new URLSearchParams(qs);
  const status = params.get('status') ?? 'all';
  const page = Number(params.get('page') ?? '1');
  return { status, page };
}

function getView(qs) {
  const { status, page } = parseQuery(qs);
  const filtered = status === 'all' ? ORDERS : ORDERS.filter((o) => o.status === status);
  const total = filtered.length;
  const start = (page - 1) * LIMIT;
  const ids = filtered.slice(start, start + LIMIT).map((o) => o.id);
  return { status, page, total, ids };
}

function nextFilterQuery(nextStatus) {
  return 'status=' + nextStatus + '&page=1';
}

const v1 = getView('status=open&page=1');
console.log('page1', v1.ids, 'of', v1.total);

