function makeCache(initial) {
  let data = { ...initial };
  return {
    get: () => ({ ...data }),
    set: (updater) => { data = updater({ ...data }); },
  };
}

const cache = makeCache({ userId: "u1", isFollowing: false, followers: 100 });

function runMutation({ next, shouldFail }, handlers) {
  const ctx = handlers.onMutate(next);
  if (shouldFail) {
    handlers.onError(ctx);
    return "error";
  }
  return "success";
}

const handlers = {
  onMutate(next) {
    const prev = cache.get();
    cache.set((d) => ({
      ...d,
      isFollowing: next,
      followers: d.followers + (next ? 1 : -1),
    }));
    return { prev };
  },
  onError(ctx) {
    cache.set(() => ({ ...ctx.prev }));
  },
};

const r1 = runMutation({ next: true, shouldFail: false }, handlers);
console.log("after success:", r1, cache.get().isFollowing, cache.get().followers);

const r2 = runMutation({ next: false, shouldFail: true }, handlers);
console.log("after error:", r2, cache.get().isFollowing, cache.get().followers);

