const OPTIONS = ["Apples", "Bananas", "Cherries", "Dates"]

function reduceKey(state, key) {
  const last = state.options.length - 1
  if (key === "Enter" || key === " ") {
    if (state.open) return { ...state, selected: state.options[state.active] }
    return { ...state, open: true }
  }
  if (key === "ArrowDown") return { ...state, active: Math.min(state.active + 1, last) }
  if (key === "ArrowUp") return { ...state, active: Math.max(state.active - 1, 0) }
  if (key === "Escape") return { ...state, open: false }
  return state
}

const keys = ["Enter", "ArrowDown", "ArrowDown", "ArrowUp", "Enter", "Escape"]
let state = { open: false, active: 0, selected: null, options: OPTIONS }
for (const k of keys) state = reduceKey(state, k)

console.log("open=", state.open)
console.log("active=", state.active)
console.log("selected=", state.selected)

