function describeSearchPanel(props) {
  const { state, results, query } = props;
  if (state === "loading") return { role: "status", text: "Searching...", ctaEnabled: false };
  if (state === "error")   return { role: "alert",  text: "Try again",   ctaEnabled: true  };
  if (state === "success") {
    const n = (results || []).length;
    if (n === 0) return { role: "status", text: "No results", ctaEnabled: false };
    return { role: "list", text: n + " results", ctaEnabled: true };
  }
  if (!query) return { role: "search", text: "Type to search", ctaEnabled: false };
  return { role: "search", text: "Ready", ctaEnabled: true };
}

const CASES = [
  { name: "loading",  props: { state: "loading" },                     wantRole: "status", wantText: "Searching...", wantCta: false },
  { name: "results",  props: { state: "success", results: [1, 2, 3] }, wantRole: "list",   wantText: "3 results",    wantCta: true  },
  { name: "empty",    props: { state: "success", results: [] },        wantRole: "status", wantText: "No results",   wantCta: false },
  { name: "error",    props: { state: "error" },                       wantRole: "alert",  wantText: "Try again",    wantCta: true  },
  { name: "disabled", props: { state: "idle", query: "" },             wantRole: "search", wantText: "Type to search", wantCta: false },
];

function runInSearchPanelTests(cases) {
  let passed = 0;
  let failed = 0;
  const failures = [];
  for (const c of cases) {
    const view = describeSearchPanel(c.props);
    const ok = view.role === c.wantRole && view.text === c.wantText && view.ctaEnabled === c.wantCta;
    if (ok) {
      passed += 1;
    } else {
      failed += 1;
      failures.push(c.name);
    }
  }
  return { passed, failed, failures };
}

const report = runInSearchPanelTests(CASES);
console.log("passed=", report.passed);
console.log("failed=", report.failed);
console.log("failures=", report.failures);

