];

function toStatus(email, res) {
  if (!res.ok) return { kind: 'error', message: `Subscribe failed (${res.status})` };
  if (res.created) return { kind: 'success', email };
  return { kind: 'empty' };
}

function describe(status) {
  const disabled = status.kind === 'loading';
  let announce = '';
  if (status.kind === 'success') announce = `Subscribed ${status.email}`;
  else if (status.kind === 'empty') announce = 'Already subscribed';
  else if (status.kind === 'error') announce = status.message;
  return { disabled, announce };
}

