const ENVS = {
  production: { NEXT_PUBLIC_API_ORIGIN: "https://api.example.com" },
  preview:    { NEXT_PUBLIC_API_ORIGIN: "https://preview.api.example.com" },
  broken:     {}
};

const PING = {
  "https://api.example.com": true,
  "https://preview.api.example.com": false
};

function resolveEnv(name) {
  const origin = ENVS[name] && ENVS[name].NEXT_PUBLIC_API_ORIGIN;
  if (!origin) {
    throw new Error(name + ": NEXT_PUBLIC_API_ORIGIN missing");
  }
  return { apiOrigin: origin };
}

function healthCheck(cfg) {
  const upstreamOk = PING[cfg.apiOrigin] === true;
  return { ok: upstreamOk, origin: cfg.apiOrigin, status: upstreamOk ? 200 : 503 };
}

const prod = healthCheck(resolveEnv("production"));
const prev = healthCheck(resolveEnv("preview"));
let bootError = "";
try {
  resolveEnv("broken");
} catch (e) {
  bootError = e.message;
}

console.log("prod", prod);
console.log("preview", prev);
console.log("boot", bootError);

