const initialState = { status: 'idle', error: null, items: ['sku-1', 'sku-2'] };

function reducer(state, action) {
  switch (action.type) {
    case 'submit':
      if (state.items.length === 0 || state.status === 'loading') return state;
      return { status: 'loading', error: null, items: state.items };
    case 'resolve':
      return { status: 'success', error: null, items: state.items };
    case 'reject':
      return { status: 'error', error: action.message, items: state.items };
    default:
      return state;
  }
}

const actions = [
  { type: 'submit' },
  { type: 'submit' },
  { type: 'reject', message: 'card declined' },
  { type: 'submit' },
  { type: 'resolve' },
];

let state = initialState;
const trace = [];
for (const action of actions) {
  state = reducer(state, action);
  trace.push(state.status);
}
console.log("trace", trace);
console.log("final", state);
console.log("itemsKept", state.items.length === initialState.items.length);
